INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "罗弘信正式授魏博节度使", "start_year": 888, "end_year": 888, "time_original": "888年七月后、八月前；具体日未载", "dynasty": "唐", "description": "朝廷任原权知魏博留后的罗弘信为魏博节度使。", "phases": [], "location_name": "魏博", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "407fe6aa-7700-5585-81cb-20014e3eec00"}, {"title": "朱全忠取蔡州南城", "start_year": 888, "end_year": 888, "time_original": "888年八月戊辰", "dynasty": "唐", "description": "朱全忠攻取蔡州南城。", "phases": [], "location_name": "蔡州南城", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "4ffacf01-e898-5efc-a803-2ffbce014bb3"}, {"title": "袁袭建议杨行密取宣州", "start_year": 888, "end_year": 888, "time_original": "888年八月；具体日未载", "dynasty": "唐", "description": "杨行密惧孙儒进逼，原想轻兵袭洪州；袁袭认为江西钟传强而宣州赵锽新据、易图，建议联孙端、张雄攻宣州，杨行密采纳。", "phases": [], "location_name": "庐州、宣州方向", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "faa0839f-e24f-5de4-8382-bebb63da879c"}, {"title": "杨行密留蔡俦守庐州并渡江", "start_year": 888, "end_year": 888, "time_original": "888年八月；具体日未载", "dynasty": "唐", "description": "杨行密令蔡俦守庐州，亲率诸将从糁潭渡江。", "phases": [], "location_name": "庐州、糁潭、江南", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "7f58836e-8f9c-5e7e-9805-a82b8eb8b77f"}, {"title": "孙端张雄为赵锽所败", "start_year": 888, "end_year": 888, "time_original": "888年八月；具体日未载", "dynasty": "唐", "description": "孙端、张雄两军先为赵锽击败。", "phases": [], "location_name": "宣州方向", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "586d814e-7105-5c52-8e02-3e5f7839ee75"}, {"title": "杨行密于曷山败苏塘漆朗", "start_year": 888, "end_year": 888, "time_original": "孙端张雄败后；具体日未载", "dynasty": "唐", "description": "赵锽部将苏塘、漆朗屯曷山。袁袭建议杨行密坚壁诱其松懈，杨行密采纳并击败二将，随后围宣州。", "phases": [], "location_name": "曷山、宣州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "c31c2641-163b-5335-956c-059522ef4783"}, {"title": "陶雅败赵乾之于九华", "start_year": 888, "end_year": 888, "time_original": "杨行密围宣州时；具体日未载", "dynasty": "唐", "description": "赵锽之兄赵乾之自池州率军救宣州，杨行密遣陶雅在九华击败其军；赵乾之奔江西，陶雅受任池州制置使。", "phases": [], "location_name": "九华、池州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "b56a268d-9aa1-5c53-a1c8-383db9298e3f"}, {"title": "朱全忠自蔡州撤军", "start_year": 888, "end_year": 888, "time_original": "888年九月", "dynasty": "唐", "description": "朱全忠因粮运不继，并认为秦宗权已残破而引军撤离蔡州。", "phases": [], "location_name": "蔡州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "701620f7-2dcc-5ea0-bd69-c2352e2d4978"}, {"title": "朱全忠遣朱珍护刘瓚赴楚州", "start_year": 888, "end_year": 888, "time_original": "888年九月丙申", "dynasty": "唐", "description": "朱全忠遣朱珍领兵护送楚州刺史刘瓚赴任。", "phases": [], "location_name": "楚州方向", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "fde413a7-fba8-55ae-9c34-4c3547ef906e"}, {"title": "钱镠遣钱銶攻徐约于苏州", "start_year": 888, "end_year": 888, "time_original": "888年九月；具体日未载", "dynasty": "唐", "description": "钱镠遣从弟钱銶率军攻苏州徐约。", "phases": [], "location_name": "苏州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "41899d57-6b91-5a1e-8bd7-1b32aa388968"}, {"title": "朱珍刘瓚击徐军取沛滕", "start_year": 888, "end_year": 888, "time_original": "888年十月", "dynasty": "唐", "description": "徐州军阻朱珍、刘瓚前进，朱珍等击退之并取沛、滕二县。", "phases": [], "location_name": "沛县、滕县", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "bc951d76-9863-548a-9ceb-227b6f99ed5b"}, {"title": "李克修败奚忠信于辽州", "start_year": 888, "end_year": 888, "time_original": "888年十月；具体日未载", "dynasty": "唐", "description": "孟方立遣奚忠信率军袭辽州，李克修迎击大败其军，俘奚忠信送晋阳。", "phases": [], "location_name": "辽州、晋阳", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "ce07e5b2-9be9-50a0-a142-a938751a1caa"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

